#: Contract facts ``OperationSpec`` does not carry, by SDK name: ``replay_omits`` (response fields a
#: replayed call leaves out), ``resume_when`` (which stream lines resume), ``opaque_cursor``, ``stop``
#: (a verb that stops work) and ``durable_unstated`` (an idempotent operation whose contract does not
#: state durability; ``OperationSpec.durable`` is True for it).
EXTRAS: dict[str, dict[str, Any]] = {
    "deployments.logs": {
        "resume_when": "source=build. Runtime lines carry no id and do not resume; follow is best effort across a reconnect"
    },
    "deployments.rotateAccessToken": {"replay_omits": ("accessToken",)},
    "platform.agents.draft": {"durable_unstated": True},
    "platform.agents.rollbackDeployment": {"durable_unstated": True},
    "platform.schedules.create": {"durable_unstated": True},
    "platform.schedules.runNow": {"durable_unstated": True},
    "runs.cancel": {"stop": True},
    "runs.interrupt": {"stop": True},
    "runs.list": {"opaque_cursor": True},
}

